const independentSections:Partial<Record<string,{heading:string;body:string}[]>>={
 'bookkeeping-assistant-duplicate-invoice-control-study':[
  {heading:'The decision this control must support',body:'The practical question is not whether two invoice files look alike. It is whether the company has enough traceable evidence to let its finance owner decide what each document represents and whether any obligation should move toward payment. A Philippines-based bookkeeping assistant can prepare that evidence by transcribing approved fields, connecting purchase and delivery records, and surfacing collisions. Vendor approval, accounting treatment, duplicate disposition, tax handling, and release of funds remain with the designated finance owner. The queue should make those decisions easier to inspect without silently making them.'},
  {heading:'Constructed cases and method',body:'We built thirty fictional invoice packets rather than examining customer accounts. They included an exact duplicate PDF, two files with the same invoice number but different totals, recurring subscription charges, a credit note, split delivery, partial purchase order, foreign currency, corrected tax, reused vendor numbering, changed bank details, employee reimbursement, and an emailed replacement. Each packet was processed against a frozen rubric. We kept document facts, matching signals, business interpretation, owner decision, and uncertainty in separate fields so a convenient match could not masquerade as approval.'},
  {heading:'What belongs in the intake record',body:'A useful record captures the approved vendor identifier, vendor name exactly as shown, invoice number, document date, receipt timestamp, currency, gross amount, tax shown, purchase-order reference, delivery or service evidence, source channel, original file hash, prior candidate matches, exception code, assigned reviewer, and final state. Corrections append a new value with a reason and owner; they do not erase the received document. A green match flag means only that defined fields aligned. It does not prove the vendor, obligation, coding, bank destination, or payment is valid.'},
  {heading:'Exact matches, near matches, and false comfort',body:'Exact file hashes and repeated identifiers are strong discovery signals, but their meaning varies. The same file may have been uploaded twice, while the same invoice number may identify a correction or a vendor numbering defect. Conversely, two different numbers can bill the same delivery. We therefore compared exact identifiers first, then amount and date proximity, and then purchase or delivery evidence. Fuzzy similarity identified candidates for review; it never rejected a bill automatically. Every layer retained its source so a reviewer could see why a pair entered the queue.'},
  {heading:'Bank-detail changes leave the ordinary lane',body:'A request to change remittance information should not be resolved inside invoice deduplication, even when the vendor name, amount, purchase order, and attachment all appear familiar. The assistant records the changed field and message source without copying account details into a general task board, then invokes the company’s separate verification control. Contact information supplied inside the change request is not treated as independent verification. Only an authorized owner updates master data. The invoice stays held until that owner records the result through the approved system.'},
  {heading:'Credits, corrections, and partial deliveries',body:'A credit note can resemble a negative duplicate, and a corrected invoice can resemble a second charge. Both need explicit relationships to the original record. The assistant links the documents, preserves every version, and records the vendor’s stated purpose without selecting the accounting treatment. For a partial delivery, the purchase order total alone cannot show that the invoice is payable. The finance owner compares receipt or service evidence with contract terms and policy. The assistant’s job is to make the missing or conflicting evidence obvious before the decision.'},
  {heading:'Exceptions that require an owner',body:'The stop list includes missing vendor master record, absent or reused invoice number, changed payment details, amount outside the purchase evidence, duplicate file hash, mismatched currency, unreadable attachment, suspicious link, employee reimbursement, tax uncertainty, unsupported rush request, and pressure to bypass review. The handoff states confirmed fields, conflicting evidence, safe current state, and one answerable question. It does not accuse a vendor of fraud or invent a reason. If no finance owner is available, the safe state is a held queue rather than an improvised approval.'},
  {heading:'A protected pilot with known answers',body:'The pilot uses fictional or properly sanitized packets labeled in advance as duplicate, legitimate recurring charge, correction, credit, partial delivery, or unresolved. Reviewers score transcription, candidate discovery, evidence linkage, correct holds, unnecessary holds, and routing separately. False negatives receive attention before throughput because a missed duplicate can advance unnoticed. False positives matter too because needless holds disrupt vendor relationships. The team records why each item advanced, waited, or was rejected and compares that reason with the known case design.'},
  {heading:'Access and reversibility',body:'The starting account needs the assigned intake queue, read access to approved vendor and purchase references, protected source files, and an exception route. It does not need vendor creation, bank-detail editing, journal approval, payment scheduling, refunds, deletion, broad exports, or account administration. Use a named login and review its actions. Corrections and state transitions must retain prior values. At the end of the pilot, remove access, verify that temporary downloads are gone, and confirm the company repository still contains the authoritative evidence and decisions. Test that a revoked account cannot reopen attachments or export the queue. Record the person who verified removal and preserve that evidence with the pilot review.'},
  {heading:'How the finance owner should review the queue',body:'The reviewer begins with changed payment details and exact-file duplicates, then examines ambiguous identifier and evidence conflicts. For each item, the reviewer can open the original document, purchase source, receipt evidence, match explanation, and exception history. A dashboard count is not enough. The owner records duplicate, legitimate, corrected, credit, rejected, or another company-defined state with a reason. Sampling completed items helps find invoices that passed because a field was copied incorrectly or a matching rule was too narrow.'},
  {heading:'What this study does not establish',body:'This constructed workflow is not an audit, fraud rate, accounting opinion, tax interpretation, or claim about Hire Assistant Near Me outcomes. IRS record guidance, GAO control standards, and NIST security controls provide public principles within their stated scope; they do not define a private company’s invoice policy or approve a payment. Contracts, jurisdictions, systems, materiality, vendor relationships, and retention duties differ. The bounded conclusion is that an assistant may prepare comparison evidence while accountable finance staff retain master-data, accounting, and payment decisions.'},
  {heading:'Buyer checklist before delegation',body:'Before hiring, the buyer should name the vendor and purchase systems, authoritative identifiers, accepted invoice channels, duplicate signals, payment-change procedure, exception owners, review times, retention rules, and access-removal process. Provide examples of a true duplicate, recurring charge, correction, credit, and unresolved pair. Test an unavailable-owner scenario. If the software cannot separate preparation from vendor or payment authority, use an owner-reviewed staging record. Expand volume only after sampled decisions can be reconstructed from sources without relying on memory or private chat.'},
  {heading:'Recovery when a duplicate advances too far',body:'Rehearse discovery after a candidate invoice has moved beyond intake. The team should be able to pause the item through authorized controls, identify the version and owner decision that advanced it, locate related purchase and receipt evidence, preserve communication, and notify finance without asking the assistant to reverse money or alter accounting records. The finance owner determines the corrective action and downstream communication. Afterward, compare the missed signal with the intake rule: was a field copied incorrectly, evidence unavailable, a match threshold too narrow, or an owner override undocumented? Update the control with a dated reason and retest the original case plus a legitimate look-alike. Recovery evidence should show timestamps, responsible owners, affected records, and verified final state without exposing bank information or credentials in the general report. Reconcile nearby invoices from the same vendor and period because the defect may affect a group rather than one file. Record the population checked, the owner who accepted the result, and the date the repaired rule returned to use.'},
 ],
 'calendar-assistant-recurring-meeting-time-zone-study':[
  {heading:'The scheduling decision begins with organizer intent',body:'A recurring meeting cannot be configured safely from a date, time, and attendee list alone. The coordinator needs to know whether the organizer intends a stable local wall-clock time, a fixed UTC instant, or another rule tied to an operational event. Those intentions diverge when seasonal offsets change. A Philippines-based calendar assistant may collect and test the rule, but the organizer decides business priority, required attendance, protected time, sensitive guests, and the final series. The written handoff must preserve that decision instead of reducing it to an abbreviation such as EST.'},
  {heading:'Constructed series used for the study',body:'We created twenty-four fictional series rather than inspecting customer calendars. Cases included weekly meetings spanning U.S. and European daylight-saving transitions, an attendee in a zone without seasonal changes, a monthly last-Friday rule, a single moved occurrence, an organizer relocation, a room resource, a holiday collision, an overnight local display, and a series copied from fixed UTC. For every series we examined the first occurrence, transition weeks, known exceptions, end boundary, and local display for each attendee. No productivity, attendance, or customer outcome was measured.'},
  {heading:'Record an IANA zone and a plain-language intention',body:'The operating record should store organizer, purpose, authoritative IANA time-zone identifier, intended local wall-clock time, recurrence rule, start and end boundaries, required and optional attendees, source of availability, conference owner, room resources, exception dates, review horizon, and approval timestamp. It should also state in ordinary language what must stay stable, such as every Tuesday at 9 a.m. in Chicago. That sentence helps a reviewer catch a technically valid recurrence that preserves the wrong thing. Zone abbreviations alone are too ambiguous for this job.'},
  {heading:'Preview transition weeks, not only the first invitation',body:'A series can look correct on creation day and shift for another attendee several months later. Some regions change clocks on different dates, and some never change. The assistant should preview instances before, during, and after each relevant offset transition within the review horizon. Record displayed times for the organizer and representative attendees. An acceptable first instance does not approve the distant series. Unexpected movement, missing occurrences, midnight crossings, or unsupported zones return to the organizer before invitations are sent.'},
  {heading:'Treat one-off exceptions as their own decisions',body:'A holiday, travel day, deadline, or room conflict may require moving one meeting without changing the series rule. The assistant should identify whether the platform is editing this occurrence, this and following occurrences, or the whole series, then show that scope before saving. A single exception retains its relationship to the master and its own approval source. Recreating the entire series to solve one collision risks duplicate invitations, lost responses, broken conference links, and silent changes to future meetings.'},
  {heading:'Availability is evidence, not surrendered priority',body:'Free time in a calendar shows that no visible event blocks the interval under current permissions. It does not prove the person wants the meeting, that private holds are unimportant, or that an executive has surrendered a protected block. The coordinator records the availability source and any visibility limits. Conflicting required attendees, sensitive external guests, or priority tradeoffs go to the organizer. The assistant may propose approved alternatives, but should not cancel another person’s event, expose private titles, or choose whose commitment matters more.'},
  {heading:'Conference links and rooms need named ownership',body:'A recurring video link can outlive an employee, inherit the wrong host, or expose controls to an unintended account. A room may be free for the first instance and unavailable later. Record the conferencing owner, authentication expectations supplied by the organization, waiting-room or dial-in source, room resource, and conflict result for sampled occurrences. The assistant does not weaken access settings to make scheduling easier. If ownership will expire or a room rule conflicts, the organizer or workplace owner selects the replacement.'},
  {heading:'Use a platform-specific protected pilot',body:'Run a frozen set of fictional series through the actual calendar platform without inviting real participants. Inspect generated recurrence data and visible instances on representative devices or views. Score the correct instant, local display, end boundary, exception preservation, attendee visibility, conference ownership, room behavior, and reversal of a mistaken edit. Include removal of assistant access. A fast setup is not successful when a distant occurrence drifts or a one-off move rewrites every future meeting.'},
  {heading:'Stop conditions for a calendar assistant',body:'Stop when organizer zone or wall-clock intent is unclear, a recurrence produces an unexpected date, required availability conflicts, a sensitive external attendee appears, the platform proposes a wider edit than requested, a local display crosses dates, the room is unavailable, or conference ownership is uncertain. The handoff states the requested series, confirmed facts, sampled conflict, current unchanged state, organizer, and decision needed. Silence is not approval. If the organizer cannot respond, leave the draft unsent instead of inventing a reasonable compromise.'},
  {heading:'Audit the series after creation',body:'The reviewer should compare the saved rule and sampled instances with the approved intention, not merely confirm that an invitation exists. Check attendee lists, visibility, conferencing, resources, exception dates, and the end boundary. Revisit distant occurrences when governments, platform behavior, offices, or attendee locations materially change. A recurring meeting is continuing configuration, not a one-time data-entry task. Record the review date and any corrected instances so later staff can distinguish an intentional exception from unexplained drift. Keep the organizer approval with that record.'},
  {heading:'Recover from a series-wide mistake',body:'Rehearse discovery that a one-occurrence edit changed the whole series. The team should freeze further edits, capture the current recurrence and exceptions, compare them with the last approved rule, identify affected invitations and resources, and let the organizer select the repair. The assistant may prepare a correction list and approved notice but should not guess which attendee responses still apply. After repair, verify transition weeks again, remove duplicates, preserve the incident record, and update the platform-specific instruction that allowed the scope error.'},
  {heading:'Limits of this calendar analysis',body:'This constructed study does not predict future government time-zone decisions, platform defects, attendee travel, or organizational priorities. The IANA Time Zone Database, RFC 5545, and NIST daylight-saving information describe public technical context; they do not decide who should attend or which meeting wins. The bounded conclusion is that an assistant can prepare and test recurrence evidence while an organizer retains priority and exception decisions. Material platform or rule changes require a new check date rather than reliance on this study.'},
  {heading:'Buyer checklist before delegating recurrence work',body:'Name the authoritative calendar, supported time-zone identifiers, organizer-intent field, permitted edit scopes, review horizon, required preview instances, sensitive-attendee rule, room and conference owners, exception workflow, audit cadence, and access-removal procedure. Supply examples of stable local time, fixed UTC, a moved occurrence, and a conflicting series. Test the tool outage and unavailable-organizer cases. If permissions cannot separate draft preparation from sending or broad cancellation, keep publication with the organizer through an approval queue.'},
  {heading:'Handoff across coordinator shifts',body:'The outgoing coordinator should list draft series, unsent changes, the organizer intention, time-zone identifiers, sampled transition dates, exceptions, conflicts, and the person expected to decide each open item. Use absolute dates and show the relevant local zones; words such as tomorrow are unsafe in a distributed team. The receiving coordinator verifies access to the cited calendar and sources before accepting ownership. A message forwarded in chat is not a completed handoff. When an organizer decision arrives, attach it to the series record so another shift does not reopen the same ambiguity or apply it to the wrong recurrence. The handoff should also distinguish invitations already sent from drafts and simulations. Confirm which account owns every conferencing link and room reservation. If the next shift cannot access a source or the organizer decision, leave the series unchanged and escalate the missing access instead of rebuilding it from copied text.'},
 ],
};

const independentTails:Record<string,{heading:string;body:string}[]>={
 'sales-assistant-crm-lead-merge-provenance-study':[
  {heading:'Why a matching email is not the final answer',body:'An identical email address is useful candidate evidence, but role inboxes, family addresses, recycled accounts, aliases, and forwarding rules weaken it. The assistant records the match and its source rather than declaring one person. A different email also does not prove two people when a contact moved employers or separates personal and work channels. The data owner decides identity after comparing collection events, account relationships, recent verification, and conflicts. The record should show which evidence supported the candidate pair and what evidence could disprove it.'},
  {heading:'Suppression survives every cleanup operation',body:'A merge must never revive a channel that was opted out, bounced, complained, or otherwise suppressed under company policy. Keep permission and suppression events with their source, timestamp, channel, and scope. If two records disagree, the safest state is no outreach until the designated owner resolves the conflict. The assistant cannot infer consent from a newer form, a cleaner record, an active opportunity, or a salesperson request. Deduplication improves record organization; it does not manufacture communication permission.'},
  {heading:'Link accounts when a destructive merge would erase meaning',body:'Parent companies, subsidiaries, consultants, franchise locations, buyers with several roles, and one person using different business identities may need relationships rather than one surviving record. Linking preserves separate ownership, opportunities, contracts, and collection history while showing the association. The assistant may prepare the proposed relationship and evidence. Sales or data owners decide whether the CRM model supports it and which users may see it. A smaller contact count is not a quality goal when it destroys commercially relevant distinctions.'},
  {heading:'Choose field precedence one field at a time',body:'Even when identity is confirmed, there is no universal winning record. A recently verified title may be current while an older record contains the controlling opt-out or the correct account relationship. The proposal lists each conflicting field, sources, verification dates, and recommended value under an owner-approved rule. Free-text notes and raw imports remain available. The reviewer approves the survivor and field choices explicitly. Bulk selection of the newest or most complete record can overwrite reliable evidence with enrichment or stale sales edits.'},
  {heading:'Make rollback part of the work sample',body:'The protected pilot includes true duplicates, namesakes, shared phones, role accounts, renamed companies, subsidiaries, opt-out conflicts, and records owned by different salespeople. After a reviewer approves a merge in the test environment, require the candidate to locate the audit record and restore both inputs. Score false merges, provenance retention, suppression preservation, relationship choice, owner routing, and rollback success separately. A cautious held pair is preferable to an irreversible merge whose logic cannot be explained.'},
  {heading:'Review the queue by risk rather than confidence alone',body:'Pairs involving suppression, active opportunities, customer complaints, contracts, billing relationships, or different owners receive earlier and more senior review than ordinary formatting duplicates. Confidence scores may order candidates but cannot replace evidence. Sample unmerged records too, because an overly conservative process can leave duplicate outreach and fragmented history. Track false merges, missed matches, lost fields, revived channels, owner changes, and reversals. Repair the matching rule when the same error recurs instead of asking assistants to compensate from memory.'},
 ],
 'ecommerce-assistant-return-request-evidence-study':[
  {heading:'Anchor the request to the exact item and policy version',body:'A return record identifies the order, item, purchase channel, order date, fulfillment event, customer request, and the policy version that applied at purchase or another owner-defined point. Bundles, gifts, subscriptions, marketplace orders, partial shipments, and replacements can share identifiers while following different paths. The assistant locates evidence and notes uncertainty. It does not choose the most favorable policy, move dates, or treat a current website page as proof of what the customer received earlier.'},
  {heading:'Carrier scans do not settle receipt disputes',body:'Tracking events help reconstruct movement but do not prove that the named customer physically received the parcel, that every item was inside, or that the condition was acceptable. Preserve the carrier event, timestamp, address scope permitted by policy, customer statement, and any merchant evidence separately. The accountable owner decides whether to replace, refund, investigate, or request more information. Customer-facing wording should acknowledge the discrepancy without presenting a carrier status as conclusive or accusing the customer of dishonesty.'},
  {heading:'Calculate windows only from approved triggers',body:'A mechanical deadline calculation is safe only when the triggering event, timezone, policy version, and treatment of weekends or holidays are defined. Order date, ship date, delivery scan, collection date, and gift receipt may produce different answers. The assistant records the inputs and calculation rule supplied by the merchant. Ambiguous or conflicting triggers go to the policy owner. A date calculator cannot decide an exception, extend a promise, or determine a legal right.'},
  {heading:'Damaged goods evidence stays descriptive',body:'Photos, videos, packaging records, and customer descriptions can support review, but they do not prove cause, authenticity, or remedy. Preserve originals and request only material the approved process needs. Do not ask a customer to handle a dangerous product, recreate a failure, or expose unrelated personal information in an image. Safety, injury, contamination, battery, regulated-product, or recall concerns leave the routine return queue for the merchant’s specialist and, where appropriate, official reporting process.'},
  {heading:'Keep payment disputes and returns connected but separate',body:'A chargeback, payment-provider case, or bank dispute may change what the merchant is permitted to do. Record its state from the approved source and alert the designated owner. The assistant should not issue a refund to make the return queue disappear, withdraw a dispute, promise how a bank will decide, or copy sensitive payment data into notes. Link the records so reviewers understand the overlap while preserving distinct owners, deadlines, evidence, and closure states.'},
  {heading:'Test ordinary remedies and uncomfortable edge cases',body:'The pilot includes an unopened item within policy, partial order, wrong item, damaged packaging, late delivery, missing scan, gift, bundle, subscription, final-sale claim, repeat return, chargeback, and safety allegation. Reviewers know the intended routing in advance. Score identity, policy version, deadline inputs, evidence minimization, safe escalation, approved wording, and reversal. Measure unsafe approvals separately from needless friction; average handling time cannot show whether either harm increased.'},
 ],
 'project-coordinator-change-request-decision-log-study':[
  {heading:'Find the governing baseline before discussing the change',body:'A request cannot be assessed against a vague current plan. The coordinator locates the approved scope, schedule, acceptance criteria, budget or capacity assumptions, and version that governed when the request arrived. If no baseline can be identified, the record stays held for the sponsor. A chat message, meeting note, or customer suggestion may be valuable input without being authority. The decision log links the request to the baseline so later reviewers can tell what changed rather than comparing two reconstructed memories.'},
  {heading:'Small wording can hide large dependency effects',body:'The constructed cases showed that a one-line due-date or deliverable edit could compress accessibility review, legal review, testing, procurement, training, or customer communication. The assistant maps affected deliverables and asks named owners for estimates or constraints. It does not calculate a compromise, approve overtime, or declare an impact negligible. Unknown dependencies remain visible. A polished request summary is dangerous when it omits the teams whose work makes the proposed date possible.'},
  {heading:'Separate an estimate from a commitment',body:'Each estimate retains its author, assumptions, range or confidence language, date, and affected version. The coordinator may collect conflicting estimates and show why they differ. It should not average them into a single promise, choose the most convenient number, or send a draft externally as an approved schedule. Sponsors and accountable specialists decide tradeoffs. Customer communication uses only the decision and conditions they authorize, with the effective version recorded.'},
  {heading:'Document work that started before approval without legitimizing it',body:'A team may begin an urgent fix or informal request before the governance record catches up. The coordinator records what started, who requested it, affected systems, current safe state, and decisions still required. Creating the record does not retroactively approve the work. The sponsor decides whether to stop, continue, roll back, or treat it under an emergency path. Preserve the timing so a later audit can distinguish prior action from subsequent authorization.'},
  {heading:'Keep rejected, withdrawn, and superseded requests',body:'A clean backlog can erase why a proposal was declined or replaced, causing the same debate to recur. Preserve the request, evidence, decision owner, reason, conditions, and successor relationship under the retention policy. A withdrawn request differs from a rejection, and a superseded request may still explain work completed under an earlier version. The assistant maintains these relationships without rewriting history or deleting dissent. Access controls can limit sensitive rationale while keeping the decision trace intact.'},
  {heading:'Rehearse a bad change and a missing owner',body:'The pilot includes cosmetic edits, regulatory deadlines, new integrations, removed deliverables, customer requests, dependency changes, emergency fixes, and work already started. One approved test change later proves harmful. The team freezes further action, finds affected records, restores the authorized baseline where appropriate, notifies owners, verifies recovery, and records lessons. A second case makes the sponsor unavailable. The safe fallback is a held decision, not approval by silence or coordinator judgment.'},
 ],
};

for(const topic of topics){
 const tail=independentTails[topic.slug];
 if(tail) independentSections[topic.slug]=[
  {heading:'Question and retained authority',body:`${topic.question} ${topic.boundary}`},
  {heading:'Constructed cases examined',body:topic.cases},
  {heading:'Operating record required',body:topic.record},
  {heading:'Findings from the case comparison',body:topic.analysis},
  {heading:'Conditions that stop routine work',body:topic.exceptions},
  {heading:'Protected pilot design',body:topic.pilot},
  ...tail,
  {heading:'Limits and bounded conclusion',body:topic.limitations},
 ];
}

function makePost(t:Topic):ResearchPost{
 const sections=independentSections[t.slug]?[...independentSections[t.slug]!]:lenses.map(([heading,key])=>({heading,body:String(t[key])}));
 if(independentTails[t.slug])sections.push(...independentTails[t.slug]);
 // A second, topic-specific implementation pass makes each report long enough to be useful
 // while preserving a clear distinction between evidence and recommendations.
 if(!independentSections[t.slug])sections.push({heading:'Implementation walkthrough',body:`Start with ${t.question.toLowerCase()} Map the trigger, source record, permitted preparation, prohibited action, review owner, response time, and closure evidence. Walk an ordinary case from intake to close, then repeat with the exception set: ${t.exceptions} Configure the tool so preparation and approval are different permissions. Preserve the original input and the approved outcome. Managers should sample completed and held cases, compare the record with source evidence, and repair instructions when two reasonable reviewers disagree. The aim is not a frictionless queue; it is a queue whose decisions can be reconstructed without relying on memory or private chat.`});
 if(!independentSections[t.slug])sections.push({heading:'Buyer decision checklist',body:`A buyer considering this lane should confirm who owns the policy, which system is authoritative, which fields the assistant can see or edit, which actions require approval, how urgent exceptions are routed, how corrections propagate, and when access ends. Provide representative examples and counterexamples. Define quality with observable evidence rather than a promise to be careful. Require the owner to record final decisions and rationale. Review source freshness, accessibility, privacy, security, contractual limits, and relevant professional advice. If the organization cannot answer these questions, the safe starting scope is collection and preparation only: ${t.boundary}`});
 if(!independentSections[t.slug])sections.push({heading:'Evidence review and challenge questions',body:`The reviewer should challenge the proposed lane with the exact ambiguity in this study: ${t.analysis} Ask what evidence could disprove the initial classification, whether the record preserves that evidence, and who may resolve the conflict. Compare the proposed action with the source documents rather than a dashboard summary. The source set for this report is ${t.sources.map(([name])=>name).join('; ')}. Those publications provide principles and public requirements within their stated scope; none evaluates Hire Assistant Near Me, a particular assistant, or the buyer's private systems. The practical recommendation is therefore conditional. It depends on the buyer maintaining the stated boundary, current policy, restricted permissions, representative tests, and an available decision owner. Record dissent and unresolved uncertainty instead of converting them into a false consensus.`});
 if(!independentSections[t.slug])sections.push({heading:'Failure rehearsal and recovery',body:`Before launch, rehearse a case that entered the normal path but later proved exceptional. Use this case pool: ${t.cases} The team should be able to freeze the action, locate every affected record, preserve the original source, notify the accountable owner, correct downstream copies, document the reason, and verify the repaired state. Then rehearse an unavailable owner and a tool outage. The safe fallback is a held queue, not an improvised decision. Review logs for unnecessary personal data and remove access at the end of the exercise. A recovery test should produce evidence that the control worked, including timestamps and ownership, without exposing credentials or confidential material in a general report. If recovery depends on undocumented memory, narrow the role before proceeding.`});
 return {slug:t.slug,title:t.title,excerpt:t.excerpt,published,image:t.image,imageAlt:t.alt,keyStats:[{value:String(sections.length),label:'Analytical sections',source:'Study structure'},{value:String(t.sources.length),label:'Authoritative sources checked',source:'Source ledger'},{value:'0',label:'Customer outcomes measured',source:'Study limitation'}],takeaways:[t.boundary,'Preserve facts, provenance, uncertainty, and owner decisions separately.','Test normal and exception cases before expanding access.'],sections,tables:[{caption:'Control boundary',columns:['State','Assistant action','Owner action'],rows:[['Inputs complete','Prepare the defined record','Review the consequential decision'],['Evidence missing or conflicting','Hold and route one clear question','Interpret, correct, or assign specialist review'],['Authority required','Do not execute','Approve, reject, or keep internally']]}],sources:t.sources.map(([name,url])=>({name:`${name} (checked ${checked})`,url})),related:[{label:'Explore the related service',href:t.service},{label:'Browse Research',href:'/research'},{label:'Discuss a bounded role brief',href:'/contact-us'}]};
}

export const oct5Hira104ResearchPosts:readonly ResearchPost[]=topics.map(makePost);
